package task

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"
	"sync"
)

const tasksFile = "tasks.json"

type Task struct {
	ID          int    `json:"id"`
	Description string `json:"description"`
	Done        bool   `json:"done"`
}

var (
	tasks    []Task
	nextID   int
	dataLock sync.Mutex // Mutex to protect access to tasks and nextID
)

func init() {
	// Initialize tasks and nextID by loading from file at package initialization
	if err := loadTasks(); err != nil {
		fmt.Fprintf(os.Stderr, "Error loading tasks: %v\n", err)
	}
}

func loadTasks() error {
	dataLock.Lock()
	defer dataLock.Unlock()

	_, err := os.Stat(tasksFile)
	if os.IsNotExist(err) {
		tasks = []Task{}
		nextID = 1
		return nil
	} else if err != nil {
		return fmt.Errorf("checking tasks file: %w", err)
	}

	file, err := ioutil.ReadFile(tasksFile)
	if err != nil {
		return fmt.Errorf("reading tasks file: %w", err)
	}

	if len(file) == 0 {
		tasks = []Task{}
		nextID = 1
		return nil
	}

	if err := json.Unmarshal(file, &tasks); err != nil {
		return fmt.Errorf("unmarshalling tasks: %w", err)
	}

	nextID = 1
	if len(tasks) > 0 {
		for _, t := range tasks {
			if t.ID >= nextID {
				nextID = t.ID + 1
			}
		}
	}
	return nil
}

func saveTasks() error {
	dataLock.Lock()
	defer dataLock.Unlock()

	data, err := json.MarshalIndent(tasks, "", "  ")
	if err != nil {
		return fmt.Errorf("marshalling tasks: %w", err)
	}

	if err := ioutil.WriteFile(tasksFile, data, 0644); err != nil {
		return fmt.Errorf("writing tasks file: %w", err)
	}
	return nil
}

func AddTask(description string) (*Task, error) {
	dataLock.Lock()
	defer dataLock.Unlock()

	if description == "" {
		return nil, fmt.Errorf("description cannot be empty")
	}

	task := Task{
		ID:          nextID,
		Description: description,
		Done:        false,
	}
	tasks = append(tasks, task)
	nextID++

	if err := saveTasks(); err != nil {
		return nil, fmt.Errorf("saving tasks: %w", err)
	}
	return &task, nil
}

func ListTasks() []Task {
	dataLock.Lock()
	defer dataLock.Unlock()
	return tasks
}

func CompleteTask(id int) (*Task, error) {
	dataLock.Lock()
	defer dataLock.Unlock()

	for i, t := range tasks {
		if t.ID == id {
			tasks[i].Done = true
			if err := saveTasks(); err != nil {
				return nil, fmt.Errorf("saving tasks: %w", err)
			}
			return &tasks[i], nil
		}
	}
	return nil, fmt.Errorf("task with ID %d not found", id)
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strconv"
	"strings"

	"todo/internal/task"
)

const ( 
	errorInvalidArgs = 42
	errorGeneral     = 1
)

// outputJSON prints the given data as JSON to stdout.
func outputJSON(data interface{}) {
	encoder := json.NewEncoder(os.Stdout)
	encoder.SetIndent("", "  ")
	if err := encoder.Encode(data); err != nil {
		fmt.Fprintf(os.Stderr, "Error encoding JSON: %v\n", err)
		os.Exit(errorGeneral)
	}
}

// printErrorAndExit prints an error message as JSON to stdout and exits with the given code.
func printErrorAndExit(err error, code int) {
	outErr := map[string]string{"error": err.Error()}
	outputJSON(outErr)
	os.Exit(code)
}

func main() {
	if len(os.Args) < 2 {
		printErrorAndExit(fmt.Errorf("invalid arguments"), errorInvalidArgs)
	}

	command := os.Args[1]

	switch command {
	case "add":
		if len(os.Args) < 3 {
			printErrorAndExit(fmt.Errorf("missing task description"), errorInvalidArgs)
		}
		description := strings.Join(os.Args[2:], " ")
		task, err := task.AddTask(description)
		if err != nil {
			printErrorAndExit(err, errorGeneral)
		}
		outputJSON(map[string]interface{}{"id": task.ID, "status": "added"})

	case "list":
		tasks := task.ListTasks()
		// Filter for undone tasks as per requirements (list all pending tasks)
		pendingTasks := []task.Task{}
		for _, t := range tasks {
			if !t.Done {
				pendingTasks = append(pendingTasks, t)
			}
		}
		outputJSON(pendingTasks)

	case "done":
		if len(os.Args) < 3 {
			printErrorAndExit(fmt.Errorf("missing task ID"), errorInvalidArgs)
		}
		id, err := strconv.Atoi(os.Args[2])
		if err != nil {
			printErrorAndExit(fmt.Errorf("invalid task ID"), errorInvalidArgs)
		}
		task, err := task.CompleteTask(id)
		if err != nil {
			printErrorAndExit(err, errorGeneral)
		}
		outputJSON(map[string]interface{}{"id": task.ID, "status": "completed"})

	default:
		printErrorAndExit(fmt.Errorf("unknown command: %s", command), errorInvalidArgs)
	}
}

